<?php
declare(strict_types=1);
namespace App\Http\Controllers;
use App\Application\Projects\ProjectConfiguration; use App\Application\Projects\ProjectService; use App\Domain\Identity\CoreIdentity; use App\Models\Need; use App\Models\Project; use App\Models\ZumraGroup; use App\Models\ZumraGroupMembership; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Pagination\LengthAwarePaginator; use Illuminate\Validation\Rule; use Illuminate\View\View;
final class ProjectController
{
    public function index(Request $request,ProjectConfiguration $configuration,ProjectService $service):View{/** @var CoreIdentity $identity */$identity=$request->attributes->get('dg_identity');$settings=$configuration->get();$query=Project::query()->where('status','!=',Project::STATUS_ARCHIVED)->latest()->limit(300);if($request->filled('domain')&&isset($settings['domains'][(string)$request->query('domain')]))$query->where('domain',$request->query('domain'));$visible=$query->get()->filter(fn(Project $p)=>$service->canView($p,$identity->reference))->values();$page=max(1,(int)$request->query('page',1));$per=(int)$settings['directory_page_size'];$projects=new LengthAwarePaginator($visible->forPage($page,$per),$visible->count(),$per,$page,['path'=>$request->url(),'query'=>$request->query()]);$groups=ZumraGroup::query()->whereIn('id',$visible->where('owner_type',Project::OWNER_GROUP)->pluck('owner_reference'))->get()->keyBy('id');return view('projects.index',compact('projects','groups')+['configuration'=>$settings]);}
    public function create(Request $request,ProjectConfiguration $configuration):View{/** @var CoreIdentity $identity */$identity=$request->attributes->get('dg_identity');$groups=ZumraGroup::query()->whereIn('id',ZumraGroupMembership::query()->where('core_identity_reference',$identity->reference)->where('status',ZumraGroupMembership::STATUS_ACTIVE)->pluck('zumra_group_id'))->orderBy('name')->get();$needs=Need::query()->where('owner_type',Need::OWNER_PERSON)->where('owner_reference',$identity->reference)->whereIn('status',[Need::STATUS_OPEN,Need::STATUS_IN_PROGRESS])->orderBy('title')->get();return view('projects.create',compact('groups','needs')+['configuration'=>$configuration->get()]);}
    public function store(Request $request,ProjectConfiguration $configuration,ProjectService $service):RedirectResponse{/** @var CoreIdentity $identity */$identity=$request->attributes->get('dg_identity');$settings=$configuration->get();$data=$request->validate(['owner_type'=>['required',Rule::in([Project::OWNER_PERSON,Project::OWNER_GROUP])],'group_reference'=>['nullable','uuid','required_if:owner_type,GROUP'],'source_need_reference'=>['nullable','uuid'],'name'=>['required','string','min:5','max:180'],'summary'=>['required','string','min:40','max:1200'],'problem'=>['required','string','min:40','max:2400'],'proposed_solution'=>['required','string','min:40','max:2400'],'beneficiaries'=>['required','string','min:20','max:1200'],'domain'=>['required',Rule::in(array_keys($settings['domains']))],'participation_mode'=>['required',Rule::in(['PHYSICAL','DIGITAL','HYBRID'])],'location'=>['nullable','string','max:160'],'objectives'=>['required','string','min:5','max:2400'],'required_capabilities'=>['nullable','string','max:2400'],'required_resources'=>['nullable','string','max:2400'],'risks'=>['nullable','string','max:2400'],'milestones'=>['required','string','min:5','max:2400'],'property_regime'=>['required',Rule::in(['PERSONAL_SUPPORTED','ZUMRA_COLLECTIVE','PARTNERSHIP','COMMUNITY_INTEREST'])],'visibility'=>['required',Rule::in([Project::VISIBILITY_PRIVATE,Project::VISIBILITY_GROUP,Project::VISIBILITY_PROGRAM,Project::VISIBILITY_PUBLIC])]]);$project=$service->create($identity->reference,$data,$settings);return redirect()->route('projects.show',$project)->with('status',$project->status===Project::STATUS_ADOPTED?'Projet adopté et enregistré. Aucun financement n’est ouvert.':'Proposition enregistrée. Elle conserve son porteur et ne vaut ni adoption ni financement.');}
    public function show(Request $request,Project $project,ProjectConfiguration $configuration,ProjectService $service):View{/** @var CoreIdentity $identity */$identity=$request->attributes->get('dg_identity');abort_unless($service->canView($project,$identity->reference),404);$group=$project->owner_type===Project::OWNER_GROUP?ZumraGroup::query()->find($project->owner_reference):null;return view('projects.show',compact('project','group')+['configuration'=>$configuration->get(),'canDecide'=>$service->canDecide($project,$identity->reference)]);}
    public function transition(Request $request,Project $project,ProjectService $service):RedirectResponse{/** @var CoreIdentity $identity */$identity=$request->attributes->get('dg_identity');$data=$request->validate(['status'=>['required',Rule::in([Project::STATUS_ADOPTED,Project::STATUS_IN_PROGRESS,Project::STATUS_COMPLETED,Project::STATUS_ARCHIVED])],'maturity'=>['nullable',Rule::in(['IDEA','EXPLORATION','TEAM','EXPERIMENT','STRUCTURED','ACTIVITY','POTENTIAL_STRUCTURE','POTENTIAL_SATELLITE'])]]);$service->transition($project,$identity->reference,$data['status'],$data['maturity']??null);return back()->with('status','L’évolution du projet est enregistrée et traçable.');}
}
